def solve_for_F(F, turns=50):
    W = {F}
    for k in range(turns):
        new_W = set(W)
        limit = 1000
        for d in range(2, limit):
            if (d-1) in W and (d+1) in W and (d-1) >= 1:
                for i in range(1, int(d**0.5) + 1):
                    if d % i == 0:
                        new_W.add(i)
                        new_W.add(d // i)
                for m in range(d, limit + 1, d):
                    new_W.add(m)
        W = new_W
        if all(i in W for i in range(1, 101)):
            return True
    return False

results = []
for F in range(2, 1000):
    if solve_for_F(F, turns=50):
        results.append(F)
        print(f"F={F}")
    if len(results) == 50:
        break

